-- Data enrichment for the comparison views, second pass. All of it is AI-drafted and unreviewed by an expert.
--
-- 1. 54 new records in the Curriculum Repository: US computing and social-studies policy for New York, California,
--    Florida, Pennsylvania, Tennessee and the national level, and German national policy. Each was researched from a page that was
--    fetched and read; the page address and how well it was confirmed are kept in the record (verificationStatus).
-- 2. A second review of the first 35 link proposals against the full record text: 6 removed, 5 reworded. Only unconfirmed proposals (relation type starting
--    with proposed_) are touched. Confirmed links are never changed here.
-- 3. 54 further proposed links, including links on single grade-band parts and on records of German states that had none.
--
-- To undo: DELETE FROM curriculum_repository_records WHERE source_repo = 'openlpm-starter-draft' AND created_at >= '2026-10-28';
-- (their links go with them) and DELETE FROM curriculum_repository_links WHERE relation_type LIKE 'proposed\_%' AND created_at >= '2026-10-28'.

SET search_path = public, extensions;

-- ============================================================================
-- 1. New records
-- ============================================================================

INSERT INTO curriculum_repository_records (id, project_id, record_type, jurisdiction, source_repo, source_record_id, title, content, access_tier, event_date)
SELECT v.id::uuid, p.id, v.record_type, v.jurisdiction, v.source_repo, v.source_record_id, v.title, v.content::jsonb, 'summary-only', NULLIF(v.event_date, '')::date
FROM (VALUES
  ('be82d592-a481-5648-8575-30b832c7951f', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-k12-cs-framework-launched', 'ACM, Code.org, CSTA, Cyber Innovation Center and NMSI launch the K-12 Computer Science Framework', '{"id":"US-EVENT-us-k12-cs-framework-launched","slug":"us-k12-cs-framework-launched","label":"ACM, Code.org, CSTA, Cyber Innovation Center and NMSI launch the K-12 Computer Science Framework","sourceUrl":"https://k12cs.org/wp-content/uploads/2016/09/PRESS-RELEASE-K%E2%80%9312-Computer-Science-Framework.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://k12cs.org/wp-content/uploads/2016/09/PRESS-RELEASE-K%E2%80%9312-Computer-Science-Framework.pdf. Primary here means the framework developers'' own press release. The source is a standards-body page and no government agency issued it. Not reviewed by a person."},"jurisdiction":"US","dateStart":"2016-10-17","dateGranularity":"day","eventType":"framework-published","temporalStatus":"past-completed","description":"Five organizations released a framework that describes core computer science concepts and practices for K-12 students and how understanding grows over time. It was written with states, districts and the computer science education community to guide the development of standards and curriculum.","verificationStatus":"primary-source-confirmed"}', '2016-10-17'),
  ('22d43498-6714-5f7c-a9c8-d3df3c69d903', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-csta-k12-cs-standards-revised-2017', 'Computer Science Teachers Association publishes the revised CSTA K-12 Computer Science Standards', '{"id":"US-EVENT-us-csta-k12-cs-standards-revised-2017","slug":"us-csta-k12-cs-standards-revised-2017","label":"Computer Science Teachers Association publishes the revised CSTA K-12 Computer Science Standards","sourceUrl":"https://csteachers.org/pk12standards/about/development/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://csteachers.org/pk12standards/about/development/. The CSTA page gives only the year. Primary here means the standards body''s own page; CSTA standards are voluntary guidance that states may adopt. Not reviewed by a person."},"jurisdiction":"US","dateStart":"2017","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","description":"The Computer Science Teachers Association published a revised set of K-12 computer science standards aligned to the 2016 K-12 Computer Science Framework. The revision updated the association''s first comprehensive standards, released in 2011.","verificationStatus":"primary-source-confirmed"}', ''),
  ('b001256a-0c62-5cc1-a983-843490197ffc', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-csta-pk12-cs-standards-2026', 'Computer Science Teachers Association publishes the 2026 PK-12 Computer Science Standards', '{"id":"US-EVENT-us-csta-pk12-cs-standards-2026","slug":"us-csta-pk12-cs-standards-2026","label":"Computer Science Teachers Association publishes the 2026 PK-12 Computer Science Standards","sourceUrl":"https://csteachers.org/pk12standards/about/development/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://csteachers.org/pk12standards/about/development/. The page places publication in summer 2026 without a day. The six specialty areas come from the CSTA standards landing page https://csteachers.org/pk12standards/ which I also fetched. Not reviewed by a person."},"jurisdiction":"US","dateStart":"2026","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","description":"CSTA published its 2026 PK-12 computer science standards. A writing team of 25 people from 18 states finalized them in spring 2026. The set has foundational standards from pre-kindergarten through grade 12 and high school specialty standards in six areas.","verificationStatus":"primary-source-confirmed"}', ''),
  ('a92211ff-9212-5374-a09d-7ff9d903d6f9', 'united-states-curriculum-repository', 'institutional-mandate-record', 'US', 'openlpm-starter-draft', 'US-MANDATE-us-essa-computer-science-well-rounded-education', 'Every Student Succeeds Act becomes law and lists computer science in the federal definition of a well-rounded education', '{"id":"US-MANDATE-us-essa-computer-science-well-rounded-education","label":"Every Student Succeeds Act becomes law and lists computer science in the federal definition of a well-rounded education","sourceUrl":"https://www.law.cornell.edu/uscode/text/20/7801","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.law.cornell.edu/uscode/text/20/7801. Cornell LII reproduces 20 U.S.C. 7801(52), added by Pub. L. 114-95 sec. 8002(21). The approval date of December 10, 2015 for Pub. L. 114-95 (S. 1177) was confirmed on https://www.govinfo.gov/content/pkg/PLAW-114publ95/html/PLAW-114publ95.htm, but I could not reach the definition itself on that page because the page text was truncated. Not reviewed by a person."},"jurisdiction":"US","issuingBody":"United States Congress and the President","mandateType":"statute","adoptionDate":"2015-12-10","dateGranularity":"day","statementText":"The Every Student Succeeds Act (Public Law 114-95) names computer science among the subjects in the federal definition of a well-rounded education. States and local school districts may add further subjects to that list.","description":"The Every Student Succeeds Act (Public Law 114-95) names computer science among the subjects in the federal definition of a well-rounded education. States and local school districts may add further subjects to that list.","verificationStatus":"secondary-source-only"}', '2015-12-10'),
  ('bcc5f936-b8ba-5d48-99c5-d1dd391e275c', 'united-states-curriculum-repository', 'institutional-mandate-record', 'US', 'openlpm-starter-draft', 'US-MANDATE-us-presidential-memo-stem-computer-science-2017', 'President directs the Education Department to prioritize STEM and computer science in grant making', '{"id":"US-MANDATE-us-presidential-memo-stem-computer-science-2017","label":"President directs the Education Department to prioritize STEM and computer science in grant making","sourceUrl":"https://www.govinfo.gov/content/pkg/FR-2017-09-28/pdf/2017-21032.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.govinfo.gov/content/pkg/FR-2017-09-28/pdf/2017-21032.pdf. Published in the Federal Register on September 28, 2017. The memorandum applies to the extent consistent with law and subject to appropriations. Not reviewed by a person."},"jurisdiction":"US","issuingBody":"President of the United States","mandateType":"other","adoptionDate":"2017-09-25","dateGranularity":"day","statementText":"A presidential memorandum told the Secretary of Education to make high-quality STEM education, with a focus on computer science, a Department priority when awarding grants from fiscal year 2018. It set a goal of at least $200 million a year in grant funds and asked for guidance on computer science education.","description":"A presidential memorandum told the Secretary of Education to make high-quality STEM education, with a focus on computer science, a Department priority when awarding grants from fiscal year 2018. It set a goal of at least $200 million a year in grant funds and asked for guidance on computer science education.","verificationStatus":"primary-source-confirmed"}', '2017-09-25'),
  ('39370f72-261d-5cef-9b7a-081a773bc083', 'united-states-curriculum-repository', 'institutional-mandate-record', 'US', 'openlpm-starter-draft', 'US-MANDATE-us-eo-14277-ai-education-for-american-youth', 'President issues Executive Order 14277 on advancing artificial intelligence education for American youth', '{"id":"US-MANDATE-us-eo-14277-ai-education-for-american-youth","label":"President issues Executive Order 14277 on advancing artificial intelligence education for American youth","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/Advancing-Artificial-Intelligence-Education-For-American-youth/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.whitehouse.gov/presidential-actions/2025/04/Advancing-Artificial-Intelligence-Education-For-American-youth/. The executive order number 14277 appears in the fetched page summary and in govinfo search results. Not reviewed by a person."},"jurisdiction":"US","issuingBody":"President of the United States","mandateType":"other","adoptionDate":"2025-04-23","dateGranularity":"day","statementText":"The order creates a White House Task Force on AI Education and a Presidential AI Challenge. It directs federal agencies to develop online K-12 AI literacy resources, calls for Education Department guidance on using grant funds for AI in instruction, and gives priority to AI in teacher training and high school AI courses.","description":"The order creates a White House Task Force on AI Education and a Presidential AI Challenge. It directs federal agencies to develop online K-12 AI literacy resources, calls for Education Department guidance on using grant funds for AI in instruction, and gives priority to AI in teacher training and high school AI courses.","verificationStatus":"primary-source-confirmed"}', '2025-04-23'),
  ('8314fcb5-f222-5318-bd02-dfb7ad76e10a', 'united-states-curriculum-repository', 'institutional-mandate-record', 'US', 'openlpm-starter-draft', 'US-MANDATE-us-ed-dear-colleague-letter-ai-education-2025', 'US Department of Education issues guidance on using federal grant funds for AI and proposes an AI grant priority', '{"id":"US-MANDATE-us-ed-dear-colleague-letter-ai-education-2025","label":"US Department of Education issues guidance on using federal grant funds for AI and proposes an AI grant priority","sourceUrl":"https://www.k12dive.com/news/education-department-issues-ai-priorities-but-what-if-the-agency-closes/754015/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.k12dive.com/news/education-department-issues-ai-priorities-but-what-if-the-agency-closes/754015/. K-12 Dive reports the letter on Tuesday July 22, 2025 and a proposed rule in the Federal Register on July 21, 2025. The ed.gov press release returned an access error so the primary text was not read. The proposed priority was open for comment, and its final status is unconfirmed. Not reviewed by a person."},"jurisdiction":"US","issuingBody":"United States Department of Education","mandateType":"other","adoptionDate":"2025-07-22","dateGranularity":"day","statementText":"The Department sent state and district leaders a Dear Colleague letter saying federal grant funds may be used for AI in curriculum tools, tutoring and career advising. It also proposed a grant priority for AI projects, which includes AI literacy in lessons and educator training in computer science and AI foundations.","description":"The Department sent state and district leaders a Dear Colleague letter saying federal grant funds may be used for AI in curriculum tools, tutoring and career advising. It also proposed a grant priority for AI projects, which includes AI literacy in lessons and educator training in computer science and AI foundations.","verificationStatus":"secondary-source-only"}', '2025-07-22'),
  ('5af11b3f-50af-5f95-a3a0-94dd3035c1df', 'new-york-curriculum-repository', 'institutional-mandate-record', 'US-NY', 'openlpm-starter-draft', 'NY-MANDATE-ny-regents-adopt-cs-digital-fluency-standards', 'NY Board of Regents adopts the first K-12 Computer Science and Digital Fluency Learning Standards', '{"id":"NY-MANDATE-ny-regents-adopt-cs-digital-fluency-standards","label":"NY Board of Regents adopts the first K-12 Computer Science and Digital Fluency Learning Standards","sourceUrl":"https://www.nysed.gov/news/2023/board-regents-adopts-first-ever-learning-standards-computer-science-and-digital-fluency","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nysed.gov/news/2023/board-regents-adopts-first-ever-learning-standards-computer-science-and-digital-fluency. The release URL carries 2023 and its roll-out table starts at August 2021, but the dateline reads December 14, 2020 and the NYSED roadmap https://www.nysed.gov/sites/default/files/programs/standards-instruction/nys-csdf-standards-timeline-and-roadmap.pdf says December 2020. Not reviewed by a person."},"jurisdiction":"US-NY","issuingBody":"New York State Board of Regents","mandateType":"standards-adoption","adoptionDate":"2020-12-14","dateGranularity":"day","statementText":"The Regents adopted New York''s first K-12 learning standards for computer science and digital fluency, organized into five concepts and grade bands from K-1 to 9-12. The state roadmap sets full implementation across all grade bands from September 2024.","description":"The Regents adopted New York''s first K-12 learning standards for computer science and digital fluency, organized into five concepts and grade bands from K-1 to 9-12. The state roadmap sets full implementation across all grade bands from September 2024.","verificationStatus":"primary-source-confirmed"}', '2020-12-14'),
  ('72c6b6d9-64a0-5ee2-8629-003e1b647d49', 'new-york-curriculum-repository', 'policy-timeline-event', 'US-NY', 'openlpm-starter-draft', 'NY-EVENT-ny-regents-conditionally-approve-cs-digital-fluency-standards', 'NY Board of Regents conditionally approves the first Computer Science and Digital Fluency Learning Standards', '{"id":"NY-EVENT-ny-regents-conditionally-approve-cs-digital-fluency-standards","slug":"ny-regents-conditionally-approve-cs-digital-fluency-standards","label":"NY Board of Regents conditionally approves the first Computer Science and Digital Fluency Learning Standards","sourceUrl":"https://www.nysed.gov/news/2020/board-regents-acts-conditionally-approve-first-ever-learning-standards-computer-science","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nysed.gov/news/2020/board-regents-acts-conditionally-approve-first-ever-learning-standards-computer-science. Some URLs for this NYSED release carry 2025 in the path, but the dateline on the fetched page reads January 13, 2020. Not reviewed by a person."},"jurisdiction":"US-NY","dateStart":"2020-01-13","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","description":"The Regents gave conditional approval to New York''s first learning standards for computer science and digital fluency. The kindergarten to grade 2 standards needed more work with early learning experts, and the full set was to return to the Board later in 2020 for final adoption.","verificationStatus":"primary-source-confirmed"}', '2020-01-13'),
  ('97843b85-5bdc-5aa6-8f62-6ec48971dc5a', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-ab-1539-computer-science-standards-statute', 'California enacts AB 1539 asking for K-12 computer science content standards', '{"id":"CA-MANDATE-ca-ab-1539-computer-science-standards-statute","label":"California enacts AB 1539 asking for K-12 computer science content standards","sourceUrl":"https://www.leginfo.ca.gov/pub/13-14/bill/asm/ab_1501-1550/ab_1539_bill_20140930_chaptered.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.leginfo.ca.gov/pub/13-14/bill/asm/ab_1501-1550/ab_1539_bill_20140930_chaptered.html. The status page https://www.leginfo.ca.gov/pub/13-14/bill/asm/ab_1501-1550/ab_1539_bill_20140930_status.html also lists chaptering by the Secretary of State on September 30, 2014. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California Legislature and Governor","mandateType":"statute","adoptionDate":"2014-09-30","dateGranularity":"day","statementText":"AB 1539 (Chapter 876, Statutes of 2014) added Education Code section 60605.4. It asks the Instructional Quality Commission to consider developing and recommending K-12 computer science content standards to the State Board by July 31, 2019. Districts may use the standards, and the work depends on funding being appropriated.","description":"AB 1539 (Chapter 876, Statutes of 2014) added Education Code section 60605.4. It asks the Instructional Quality Commission to consider developing and recommending K-12 computer science content standards to the State Board by July 31, 2019. Districts may use the standards, and the work depends on funding being appropriated.","verificationStatus":"primary-source-confirmed"}', '2014-09-30'),
  ('7fcff5d2-e1c1-5b3b-aab4-a742465c5a13', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-sbe-adopts-computer-science-standards-2018', 'California State Board of Education adopts the state''s first K-12 computer science standards', '{"id":"CA-MANDATE-ca-sbe-adopts-computer-science-standards-2018","label":"California State Board of Education adopts the state''s first K-12 computer science standards","sourceUrl":"https://beverlypress.com/2018/09/state-board-education-approves-computer-science-standards/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://beverlypress.com/2018/09/state-board-education-approves-computer-science-standards/. The California Department of Education pages blocked automated access, so the primary page was not read. The article is dated September 13, 2018. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California State Board of Education","mandateType":"standards-adoption","adoptionDate":"2018-09-06","dateGranularity":"day","statementText":"The State Board of Education approved California''s first computer science standards for K-12 students. They cover core computer science concepts, such as algorithms and programming, and core practices, such as creating computational artifacts.","description":"The State Board of Education approved California''s first computer science standards for K-12 students. They cover core computer science concepts, such as algorithms and programming, and core practices, such as creating computational artifacts.","verificationStatus":"secondary-source-only"}', '2018-09-06'),
  ('1f5a4741-9917-5d2c-b581-0bbeb7f11035', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-ab-2876-ai-literacy-curriculum-frameworks', 'California enacts AB 2876 on AI literacy in school curriculum frameworks', '{"id":"CA-MANDATE-ca-ab-2876-ai-literacy-curriculum-frameworks","label":"California enacts AB 2876 on AI literacy in school curriculum frameworks","sourceUrl":"https://calmatters.digitaldemocracy.org/bills/ca_202320240ab2876","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://calmatters.digitaldemocracy.org/bills/ca_202320240ab2876. The date is the chaptering date shown on the bill tracker. The page does not state the Governor''s approval date, and the official leginfo page returned an access error. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California Legislature and Governor","mandateType":"statute","adoptionDate":"2024-09-29","dateGranularity":"day","statementText":"AB 2876 (Chapter 927, Statutes of 2024) asks the Instructional Quality Commission to consider adding AI literacy content to the mathematics, science and history-social science frameworks when they are next revised after January 1, 2025. It also asks the Commission to consider AI literacy when evaluating instructional materials for those subjects.","description":"AB 2876 (Chapter 927, Statutes of 2024) asks the Instructional Quality Commission to consider adding AI literacy content to the mathematics, science and history-social science frameworks when they are next revised after January 1, 2025. It also asks the Commission to consider AI literacy when evaluating instructional materials for those subjects.","verificationStatus":"secondary-source-only"}', '2024-09-29'),
  ('899a708d-5fd2-5f7b-a917-7be0777836de', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-hb-495-2018-computer-science-instruction', 'Florida enacts CS/HB 495 with requirements for K-12 computer science instruction', '{"id":"FL-MANDATE-fl-hb-495-2018-computer-science-instruction","label":"Florida enacts CS/HB 495 with requirements for K-12 computer science instruction","sourceUrl":"https://www.flsenate.gov/Session/Bill/2018/495","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flsenate.gov/Session/Bill/2018/495. The bill page does not spell out the requirements. The current text of section 1007.2616 (read at leg.state.fl.us) has public schools give K-12 students chances to learn computer science, with computer science courses in middle and high school. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida Legislature and Governor","mandateType":"statute","adoptionDate":"2018-04-06","dateGranularity":"day","effectiveFrom":"2018-07-01","statementText":"CS/HB 495 (Chapter 2018-150) is a K-12 public education bill that includes requirements for specified computer science instruction and cites section 1007.2616, Florida Statutes. The Governor approved it on April 6, 2018, and it took effect July 1, 2018.","description":"CS/HB 495 (Chapter 2018-150) is a K-12 public education bill that includes requirements for specified computer science instruction and cites section 1007.2616, Florida Statutes. The Governor approved it on April 6, 2018, and it took effect July 1, 2018.","verificationStatus":"primary-source-confirmed"}', '2018-04-06'),
  ('7e7fe004-2b31-572d-bc82-a30473a6aba2', 'florida-curriculum-repository', 'policy-timeline-event', 'US-FL', 'openlpm-starter-draft', 'FL-EVENT-fl-rule-development-computer-science-standards-2024', 'Florida State Board of Education publishes notice to update the state computer science standards', '{"id":"FL-EVENT-fl-rule-development-computer-science-standards-2024","slug":"fl-rule-development-computer-science-standards-2024","label":"Florida State Board of Education publishes notice to update the state computer science standards","sourceUrl":"https://www.flrules.org/gateway/View_notice.asp?id=28386291","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flrules.org/gateway/View_notice.asp?id=28386291. The workshop date comes from the register PDF https://flrules.org/faw/fawdocuments/fawvolumefolders2024/50104/50104doc.pdf, which I read. Not reviewed by a person."},"jurisdiction":"US-FL","dateStart":"2024-05-28","dateGranularity":"day","eventType":"standards-revision-begins","temporalStatus":"past-completed","description":"The Department of Education published a notice of rule development for amendments to Rule 6A-1.09401, Student Performance Standards. The stated purpose was to update Florida''s state academic standards for computer science. A rule development workshop was set for June 12, 2024.","verificationStatus":"primary-source-confirmed"}', '2024-05-28'),
  ('cb688402-171a-5dfa-bd09-a003a167e04f', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-rule-6a-1-09401-computer-science-standards-2024', 'Florida State Board of Education rule listing the 2024 computer science standards takes effect', '{"id":"FL-MANDATE-fl-rule-6a-1-09401-computer-science-standards-2024","label":"Florida State Board of Education rule listing the 2024 computer science standards takes effect","sourceUrl":"https://www.flrules.org/gateway/View_notice.asp?id=28634320","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flrules.org/gateway/View_notice.asp?id=28634320. The Board vote date was not confirmed from a fetched page. A July 24, 2024 Board agenda item appears only in search results. Cornell LII''s copy of the rule also lists the 2024 computer science standards and an amendment effective 8/27/2024. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida State Board of Education","mandateType":"standards-adoption","adoptionDate":"2024-08-27","dateGranularity":"day","effectiveFrom":"2024-08-27","statementText":"Rule 6A-1.09401, Student Performance Standards, took effect in an amended form on August 27, 2024. Its reference list includes Florida''s State Academic Standards for Computer Science, 2024. The July 2, 2024 version of the same rule listed no computer science standards.","description":"Rule 6A-1.09401, Student Performance Standards, took effect in an amended form on August 27, 2024. Its reference list includes Florida''s State Academic Standards for Computer Science, 2024. The July 2, 2024 version of the same rule listed no computer science standards.","verificationStatus":"primary-source-confirmed"}', '2024-08-27'),
  ('cbf33ff3-7f35-5a75-89b8-8e6dcfd852ff', 'florida-curriculum-repository', 'policy-timeline-event', 'US-FL', 'openlpm-starter-draft', 'FL-EVENT-fl-rule-6a-1-09412-computer-science-course-requirements-2024', 'Florida State Board of Education begins rulemaking on K-12 course requirements including computer science courses', '{"id":"FL-EVENT-fl-rule-6a-1-09412-computer-science-course-requirements-2024","slug":"fl-rule-6a-1-09412-computer-science-course-requirements-2024","label":"Florida State Board of Education begins rulemaking on K-12 course requirements including computer science courses","sourceUrl":"https://www.flrules.org/gateway/View_notice.asp?id=28710465","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flrules.org/gateway/View_notice.asp?id=28710465. The December 24, 2024 effective date comes from final notice https://www.flrules.org/gateway/View_notice.asp?id=29042593, which lists a Computer Science reference document but does not describe the changes. Not reviewed by a person."},"jurisdiction":"US-FL","dateStart":"2024-09-06","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","description":"A notice of rule development for Rule 6A-1.09412, Course Requirements for Grades K-12, said the amendments would include changes to requirements for K-12 computer science courses. The amended rule took effect on December 24, 2024.","verificationStatus":"primary-source-confirmed"}', '2024-09-06'),
  ('7b225399-57e0-5fe1-9cdf-7c2453ecea39', 'pennsylvania-curriculum-repository', 'policy-timeline-event', 'US-PA', 'openlpm-starter-draft', 'PA-EVENT-pa-sbe-endorses-csta-k12-cs-standards-2018', 'Pennsylvania State Board of Education approves a resolution endorsing the CSTA K-12 Computer Science Standards', '{"id":"PA-EVENT-pa-sbe-endorses-csta-k12-cs-standards-2018","slug":"pa-sbe-endorses-csta-k12-cs-standards-2018","label":"Pennsylvania State Board of Education approves a resolution endorsing the CSTA K-12 Computer Science Standards","sourceUrl":"https://pa.gov/agencies/stateboard/resources/board-actions/archived-board-actions","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://pa.gov/agencies/stateboard/resources/board-actions/archived-board-actions. This is an endorsement resolution. The Board''s page of academic standards published in the Pennsylvania Bulletin (https://www.pa.gov/agencies/stateboard/resources/regulations--policy/state-academic-standards.html) lists no computer science set. The archive shows titles only, so the resolution text was not read. Not reviewed by a person."},"jurisdiction":"US-PA","dateStart":"2018-01-11","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","description":"The State Board of Education approved a resolution endorsing the K-12 computer science standards developed by the Computer Science Teachers Association. The Board''s archive lists the action under January 11, 2018.","verificationStatus":"primary-source-confirmed"}', '2018-01-11'),
  ('ef987f76-efd6-5b4d-abef-91d4b5e3abbe', 'pennsylvania-curriculum-repository', 'policy-timeline-event', 'US-PA', 'openlpm-starter-draft', 'PA-EVENT-pa-pde-framework-cs-7-12-program-guidelines-2018', 'Pennsylvania Department of Education approves the Framework for Computer Science 7-12 Program Guidelines', '{"id":"PA-EVENT-pa-pde-framework-cs-7-12-program-guidelines-2018","slug":"pa-pde-framework-cs-7-12-program-guidelines-2018","label":"Pennsylvania Department of Education approves the Framework for Computer Science 7-12 Program Guidelines","sourceUrl":"https://www.pa.gov/agencies/education/programs-and-services/educators/certification/help/certification-faqs/stem-and-computer-science.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.pa.gov/agencies/education/programs-and-services/educators/certification/help/certification-faqs/stem-and-computer-science.html. The page gives the month only and does not link a document I could read. Not reviewed by a person."},"jurisdiction":"US-PA","dateStart":"2018-12","dateGranularity":"month","eventType":"framework-published","temporalStatus":"past-completed","description":"The Pennsylvania Department of Education developed and approved a framework of program guidelines for computer science in grades 7 to 12 in December 2018. The same department page records the State Board''s January 2018 endorsement of the CSTA standards.","verificationStatus":"primary-source-confirmed"}', ''),
  ('f94dc459-3683-57e0-b9f3-0be16ed9f25e', 'tennessee-curriculum-repository', 'institutional-mandate-record', 'US-TN', 'openlpm-starter-draft', 'TN-MANDATE-tn-sbe-approves-k8-computer-science-standards-2018', 'Tennessee State Board of Education gives final approval to the state''s first K-8 computer science standards', '{"id":"TN-MANDATE-tn-sbe-approves-k8-computer-science-standards-2018","label":"Tennessee State Board of Education gives final approval to the state''s first K-8 computer science standards","sourceUrl":"https://tri-statedefender.com/tennessee-approves-first-ever-computer-science-standards-for-k-8-schools/07/31/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://tri-statedefender.com/tennessee-approves-first-ever-computer-science-standards-for-k-8-schools/07/31/. The Tri-State Defender repost names Friday, July 27, 2018. The Chalkbeat original at https://www.chalkbeat.org:443/tennessee/2018/7/27/21107006/tennessee-approves-its-first-ever-computer-science-standards-for-k-8-schools is dated July 27, 2018 and gives the 2011 and fall 2019 details. Tennessee Department of Education pages blocked automated access. Not reviewed by a person."},"jurisdiction":"US-TN","issuingBody":"Tennessee State Board of Education","mandateType":"standards-adoption","adoptionDate":"2018-07-27","dateGranularity":"day","statementText":"The State Board gave final approval to Tennessee''s first computer science standards for elementary and middle schools. They replaced computer technology standards last revised in 2011, and the benchmarks were set to reach classrooms in fall 2019.","description":"The State Board gave final approval to Tennessee''s first computer science standards for elementary and middle schools. They replaced computer technology standards last revised in 2011, and the benchmarks were set to reach classrooms in fall 2019.","verificationStatus":"secondary-source-only"}', '2018-07-27'),
  ('af74881b-7e6f-5c22-a41a-7bcbd54467bb', 'tennessee-curriculum-repository', 'institutional-mandate-record', 'US-TN', 'openlpm-starter-draft', 'TN-MANDATE-tn-public-chapter-979-computer-science-2022', 'Tennessee General Assembly passes Public Chapter 979 setting computer science requirements for K-12 schools', '{"id":"TN-MANDATE-tn-public-chapter-979-computer-science-2022","label":"Tennessee General Assembly passes Public Chapter 979 setting computer science requirements for K-12 schools","sourceUrl":"https://tnfirefly.com/news/20220928/tennessee-students-to-see-expanded-computer-science-instruction","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://tnfirefly.com/news/20220928/tennessee-students-to-see-expanded-computer-science-instruction. Only the year is confirmed from a fetched page. The Tennessee Code section 49-1-307 text (FindLaw, https://codes.findlaw.com/tn/title-49-education/tn-code-sect-49-1-307/) has the State Board adopt computer science standards, available for 2023-2024 and required from 2024-2025, but I could not confirm from a fetched page that Public Chapter 979 enacted it. Official Tennessee sites blocked automated access. Sources differ on whether middle-school students must take the course or only have access to it. Not reviewed by a person."},"jurisdiction":"US-TN","issuingBody":"Tennessee General Assembly","mandateType":"statute","adoptionDate":"2022","dateGranularity":"year","statementText":"Public Chapter 979 of 2022 passed the General Assembly unanimously. Elementary schools give each student grade-appropriate computer science education, middle schools provide computer science for at least one grading period, and high school students on a traditional diploma earn at least one computer science credit.","description":"Public Chapter 979 of 2022 passed the General Assembly unanimously. Elementary schools give each student grade-appropriate computer science education, middle schools provide computer science for at least one grading period, and high school students on a traditional diploma earn at least one computer science credit.","verificationStatus":"secondary-source-only"}', ''),
  ('a3d02265-8673-500a-b86e-25c12aa505e1', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-ncss-c3-framework-released-2013', 'National Council for the Social Studies releases the C3 Framework for state social studies standards', '{"id":"US-EVENT-us-ncss-c3-framework-released-2013","slug":"us-ncss-c3-framework-released-2013","label":"National Council for the Social Studies releases the C3 Framework for state social studies standards","sourceUrl":"https://archive.civicyouth.org/?p=5891","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://archive.civicyouth.org/?p=5891. The CIRCLE post and an American Historical Association article are both dated 17 September 2013, but Education Week says the document went online the week before, so only the month is given. NCSS''s own page could not be fetched. Not reviewed by a person."},"jurisdiction":"US","dateStart":"2013-09","dateGranularity":"month","eventType":"framework-published","temporalStatus":"past-completed","description":"NCSS and partner organizations released the College, Career, and Civic Life (C3) Framework, guidance for states that are revising their social studies standards. It covers civics, economics, geography and history and is organized around an inquiry approach to teaching.","verificationStatus":"secondary-source-only"}', ''),
  ('f0a774e7-0c5e-557a-9291-3a708f350181', 'united-states-curriculum-repository', 'institutional-mandate-record', 'US', 'openlpm-starter-draft', 'US-MANDATE-us-essa-american-history-civics-program-2015', 'Congress enacts the Every Student Succeeds Act, which authorizes a federal American history and civics education program', '{"id":"US-MANDATE-us-essa-american-history-civics-program-2015","label":"Congress enacts the Every Student Succeeds Act, which authorizes a federal American history and civics education program","sourceUrl":"https://www.govinfo.gov/content/pkg/PLAW-114publ95/html/PLAW-114publ95.htm","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.govinfo.gov/content/pkg/PLAW-114publ95/html/PLAW-114publ95.htm. Read in the enacted public law text on govinfo (approval line: December 10, 2015). The record covers only this one program. It leaves out the rest of the Act. Not reviewed by a person."},"jurisdiction":"US","issuingBody":"United States Congress","mandateType":"statute","adoptionDate":"2015-12-10","dateGranularity":"day","statementText":"The Every Student Succeeds Act (Public Law 114-95) was approved on December 10, 2015. In Title II, sections 2231 to 2233 authorize the Secretary of Education to run an American history and civics education program, including Presidential and Congressional Academies and national grant activities.","description":"The Every Student Succeeds Act (Public Law 114-95) was approved on December 10, 2015. In Title II, sections 2231 to 2233 authorize the Secretary of Education to run an American history and civics education program, including Presidential and Congressional Academies and national grant activities.","verificationStatus":"primary-source-confirmed"}', '2015-12-10'),
  ('7e2d942a-f8d4-5b63-a912-ac00aba48b99', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-ead-roadmap-released-2021', 'Educating for American Democracy releases its Roadmap for K-12 history and civic education', '{"id":"US-EVENT-us-ead-roadmap-released-2021","slug":"us-ead-roadmap-released-2021","label":"Educating for American Democracy releases its Roadmap for K-12 history and civic education","sourceUrl":"https://news.asu.edu/20210302-solutions-asu-diverse-team-collaborators-release-roadmap-educating-american-democracy","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://news.asu.edu/20210302-solutions-asu-diverse-team-collaborators-release-roadmap-educating-american-democracy. ASU dates the release March 2, 2021 and the Harvard Gazette story reads as March 1, so only the month is given. The seven themes and the funding statement come from the project''s own site (educatingforamericandemocracy.org/the-report/). Not reviewed by a person."},"jurisdiction":"US","dateStart":"2021-03","dateGranularity":"month","eventType":"framework-published","temporalStatus":"past-completed","description":"A team led by iCivics, Harvard, Arizona State University and Tufts released the Roadmap to Educating for American Democracy, a framework for K-12 history and civic education built around seven themes. The project describes the themes as a starting point for designing standards, curricula and lessons. Funding came from the National Endowment for the Humanities and the US Department of Education.","verificationStatus":"secondary-source-only"}', ''),
  ('09614174-e05b-5ca6-a46e-fdbebe184aee', 'united-states-curriculum-repository', 'policy-timeline-event', 'US', 'openlpm-starter-draft', 'US-EVENT-us-naep-civics-framework-update-launched-2026', 'National Assessment Governing Board launches an update of the NAEP Civics Assessment Framework', '{"id":"US-EVENT-us-naep-civics-framework-update-launched-2026","slug":"us-naep-civics-framework-update-launched-2026","label":"National Assessment Governing Board launches an update of the NAEP Civics Assessment Framework","sourceUrl":"https://www.nagb.gov/news-and-events/news-releases/2026/release-board-meeting-actions-051526.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nagb.gov/news-and-events/news-releases/2026/release-board-meeting-actions-051526.html. The release says subject-matter and assessment experts and an educator advisory committee will be convened and more public comment is planned. Not reviewed by a person."},"jurisdiction":"US","dateStart":"2026-05-15","dateGranularity":"day","eventType":"standards-revision-begins","temporalStatus":"past-completed","description":"On May 15, 2026 the National Assessment Governing Board approved a charge to begin updating the NAEP Civics Assessment Framework, which would guide civics assessments from 2032. The Board also finalized plans for optional state-level results in 8th and 12th grade civics for states that opt in.","verificationStatus":"primary-source-confirmed"}', '2026-05-15'),
  ('9d456231-aca4-5d1f-80cf-984d5e102892', 'new-york-curriculum-repository', 'institutional-mandate-record', 'US-NY', 'openlpm-starter-draft', 'NY-MANDATE-ny-regents-k12-social-studies-framework-adopted-2014', 'New York Board of Regents adopts the K-12 Social Studies Framework', '{"id":"NY-MANDATE-ny-regents-k12-social-studies-framework-adopted-2014","label":"New York Board of Regents adopts the K-12 Social Studies Framework","sourceUrl":"https://www.nysed.gov/news/2015/regents-adopt-social-studies-framework-new-guidelines-will-prepare-students-citizenship","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nysed.gov/news/2015/regents-adopt-social-studies-framework-new-guidelines-will-prepare-students-citizenship. The page address contains 2015 but the release itself is dated April 29, 2014. Not reviewed by a person."},"jurisdiction":"US-NY","issuingBody":"New York State Board of Regents","mandateType":"framework","adoptionDate":"2014-04-29","dateGranularity":"day","statementText":"The Board of Regents adopted the New York State K-12 Social Studies Framework, which lists key ideas and concepts for each grade level and combines literacy skills with social studies practices. The state''s five social studies standards and the kindergarten-to-grade-12 course order stay in place.","description":"The Board of Regents adopted the New York State K-12 Social Studies Framework, which lists key ideas and concepts for each grade level and combines literacy skills with social studies practices. The state''s five social studies standards and the kindergarten-to-grade-12 course order stay in place.","verificationStatus":"primary-source-confirmed"}', '2014-04-29'),
  ('218f2a76-bbbe-573c-bae4-1d4aada4d412', 'new-york-curriculum-repository', 'institutional-mandate-record', 'US-NY', 'openlpm-starter-draft', 'NY-MANDATE-ny-nysed-grades-9-12-social-studies-framework-revised-2017', 'New York State Education Department issues the revised Grades 9-12 Social Studies Framework', '{"id":"NY-MANDATE-ny-nysed-grades-9-12-social-studies-framework-revised-2017","label":"New York State Education Department issues the revised Grades 9-12 Social Studies Framework","sourceUrl":"https://www.nysed.gov/sites/default/files/programs/standards-instruction/framework-9-12-with-2017-updates.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nysed.gov/sites/default/files/programs/standards-instruction/framework-9-12-with-2017-updates.pdf. The cover and contents give a revision date only. The department''s social studies page also lists a March 2016 revision of the K-8 framework. Whether the Regents voted on these revisions was not checked. Not reviewed by a person."},"jurisdiction":"US-NY","issuingBody":"New York State Education Department","mandateType":"standards-revision","adoptionDate":"2017-02","dateGranularity":"month","statementText":"The State Education Department issued a revised Grades 9-12 Social Studies Framework dated February 2017. It covers Global History and Geography in grades 9 and 10, United States History and Government in grade 11, and Participation in Government and Civics and Economics in grade 12.","description":"The State Education Department issued a revised Grades 9-12 Social Studies Framework dated February 2017. It covers Global History and Geography in grades 9 and 10, United States History and Government in grade 11, and Participation in Government and Civics and Economics in grade 12.","verificationStatus":"primary-source-confirmed"}', ''),
  ('884f4943-fbeb-567c-9454-50372b2fb265', 'new-york-curriculum-repository', 'institutional-mandate-record', 'US-NY', 'openlpm-starter-draft', 'NY-MANDATE-ny-regents-seal-of-civic-readiness-pathway-approved-2021', 'New York Board of Regents approves the Seal of Civic Readiness and Civics Pathway for all high schools', '{"id":"NY-MANDATE-ny-regents-seal-of-civic-readiness-pathway-approved-2021","label":"New York Board of Regents approves the Seal of Civic Readiness and Civics Pathway for all high schools","sourceUrl":"https://www.nysed.gov/sites/default/files/programs/curriculum-instruction/civic-readiness-manual.docx","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.nysed.gov/sites/default/files/programs/curriculum-instruction/civic-readiness-manual.docx. Day not stated in the department manual. A May 10, 2021 department release describes the original proposal and pilot; the application detail comes from nysed.gov/curriculum-instruction/seal-civic-readiness. Not reviewed by a person."},"jurisdiction":"US-NY","issuingBody":"New York State Board of Regents","mandateType":"other","adoptionDate":"2021-09","dateGranularity":"month","statementText":"In September 2021 the Regents approved the Seal of Civic Readiness +1 Civics Pathway for all high schools beginning in the 2022-23 school year. A pilot with 117 schools ran in 2021-22. The Seal recognizes high civic knowledge and participation, and districts and schools apply to offer it.","description":"In September 2021 the Regents approved the Seal of Civic Readiness +1 Civics Pathway for all high schools beginning in the 2022-23 school year. A pilot with 117 schools ran in 2021-22. The Seal recognizes high civic knowledge and participation, and districts and schools apply to offer it.","verificationStatus":"primary-source-confirmed"}', ''),
  ('51e04b36-38d0-59fe-8918-2f9319840f5a', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-sbe-history-social-science-content-standards-adopted-1998', 'California State Board of Education adopts the History-Social Science Content Standards', '{"id":"CA-MANDATE-ca-sbe-history-social-science-content-standards-adopted-1998","label":"California State Board of Education adopts the History-Social Science Content Standards","sourceUrl":"https://www.leginfo.ca.gov/pub/13-14/bill/sen/sb_1051-1100/sb_1057_cfa_20140826_154044_sen_floor.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.leginfo.ca.gov/pub/13-14/bill/sen/sb_1051-1100/sb_1057_cfa_20140826_154044_sen_floor.html. Date comes from an official California Senate floor analysis (August 2014). No State Board page was used because the Department of Education site blocked fetching. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California State Board of Education","mandateType":"standards-adoption","adoptionDate":"1998-10-09","dateGranularity":"day","statementText":"The California State Board of Education adopted the state''s history-social science content standards on October 9, 1998. A 2014 Senate bill analysis still described them as the current standards and noted that a bill (SB 1057) proposed revising them.","description":"The California State Board of Education adopted the state''s history-social science content standards on October 9, 1998. A 2014 Senate bill analysis still described them as the current standards and noted that a bill (SB 1057) proposed revising them.","verificationStatus":"primary-source-confirmed"}', '1998-10-09'),
  ('66c87047-122d-51de-9e7c-44c2dfb18867', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-sbe-history-social-science-framework-adopted-2016', 'California State Board of Education adopts the History-Social Science Framework', '{"id":"CA-MANDATE-ca-sbe-history-social-science-framework-adopted-2016","label":"California State Board of Education adopts the History-Social Science Framework","sourceUrl":"https://www.caeducatorstogether.org/resources/126513/history-social-sciences-framework","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.caeducatorstogether.org/resources/126513/history-social-sciences-framework. Teacher-community site that reposts the Department of Education framework. A July 2016 local news article and a 2018 CSBA post also confirm approval in 2016 but give no exact day. The Department of Education site blocked fetching. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California State Board of Education","mandateType":"framework","adoptionDate":"2016-07-14","dateGranularity":"day","statementText":"The State Board adopted the History-Social Science Framework for California Public Schools, Kindergarten Through Grade Twelve, a curriculum framework with chapters for each grade or grade span. It is meant to work alongside the state''s existing content standards, which are printed in an appendix.","description":"The State Board adopted the History-Social Science Framework for California Public Schools, Kindergarten Through Grade Twelve, a curriculum framework with chapters for each grade or grade span. It is meant to work alongside the state''s existing content standards, which are printed in an appendix.","verificationStatus":"secondary-source-only"}', '2016-07-14'),
  ('bb8fcccf-af58-5aea-925c-d39bb6753ad0', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-sbe-ethnic-studies-model-curriculum-adopted-2021', 'California State Board of Education approves the Ethnic Studies Model Curriculum', '{"id":"CA-MANDATE-ca-sbe-ethnic-studies-model-curriculum-adopted-2021","label":"California State Board of Education approves the Ethnic Studies Model Curriculum","sourceUrl":"https://edcal.acsa.org/state-board-approves-historic-ethnic-studies-guidance","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://edcal.acsa.org/state-board-approves-historic-ethnic-studies-guidance. The March 18 day comes from a news release quoted in the article. The 2021 adoption is also stated in an August 23, 2023 State Board letter on gov.ca.gov. Ethnic studies is a related subject within history-social science, included because it is part of the state''s social studies offering. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California State Board of Education","mandateType":"framework","adoptionDate":"2021-03-18","dateGranularity":"day","statementText":"The State Board approved a statewide Ethnic Studies Model Curriculum in March 2021. A later State Board letter describes it as grounded in African American, Native American, Asian/Pacific Islander American and Latinx American studies, with room for local adaptation.","description":"The State Board approved a statewide Ethnic Studies Model Curriculum in March 2021. A later State Board letter describes it as grounded in African American, Native American, Asian/Pacific Islander American and Latinx American studies, with room for local adaptation.","verificationStatus":"secondary-source-only"}', '2021-03-18'),
  ('54a1a2e2-53da-57a3-8ddb-52f29aff3e47', 'california-curriculum-repository', 'institutional-mandate-record', 'US-CA', 'openlpm-starter-draft', 'CA-MANDATE-ca-ab101-ethnic-studies-graduation-requirement-2021', 'California enacts AB 101, adding an ethnic studies course to high school graduation requirements', '{"id":"CA-MANDATE-ca-ab101-ethnic-studies-graduation-requirement-2021","label":"California enacts AB 101, adding an ethnic studies course to high school graduation requirements","sourceUrl":"https://www.gov.ca.gov/wp-content/uploads/2021/10/AB-101-Signing-Message-PDF.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.gov.ca.gov/wp-content/uploads/2021/10/AB-101-Signing-Message-PDF.pdf. The 2025-26 offering date comes from an August 23, 2023 State Board letter on gov.ca.gov (Chapter 661, Statutes of 2021). The funding condition comes from a mirror of Education Code 51225.3(f) on california.public.law, so it is a secondary reading. Not reviewed by a person."},"jurisdiction":"US-CA","issuingBody":"California Legislature and Governor","mandateType":"graduation-requirement","adoptionDate":"2021-10-08","dateGranularity":"day","statementText":"Governor Newsom signed AB 101 on October 8, 2021. It adds a one-semester ethnic studies course as a high school graduation requirement starting with students graduating in 2029-30, and schools are to offer the course from 2025-26. The Education Code text makes the change operative only if the Legislature appropriates funds.","description":"Governor Newsom signed AB 101 on October 8, 2021. It adds a one-semester ethnic studies course as a high school graduation requirement starting with students graduating in 2029-30, and schools are to offer the course from 2025-26. The Education Code text makes the change operative only if the Legislature appropriates funds.","verificationStatus":"primary-source-confirmed"}', '2021-10-08'),
  ('82ce7308-fce3-555d-8d7e-c595911ee562', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-hb807-civics-education-review-2019', 'Florida enacts HB 807 requiring a review of civics course standards and materials', '{"id":"FL-MANDATE-fl-hb807-civics-education-review-2019","label":"Florida enacts HB 807 requiring a review of civics course standards and materials","sourceUrl":"https://www.flsenate.gov/Session/Bill/2019/807","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flsenate.gov/Session/Bill/2019/807. The Florida Senate bill page lists approval by the Governor on June 26, 2019. A 2021 House staff analysis confirms the standards review began in 2020. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida Legislature","mandateType":"statute","adoptionDate":"2019-06-26","dateGranularity":"day","statementText":"CS/HB 807 (Civics Education), Chapter 2019-150, has the Commissioner of Education review civics instructional materials and test specifications and make recommendations. It also requires the Department of Education to review the statewide civics education course standards.","description":"CS/HB 807 (Civics Education), Chapter 2019-150, has the Commissioner of Education review civics instructional materials and test specifications and make recommendations. It also requires the Department of Education to review the statewide civics education course standards.","verificationStatus":"primary-source-confirmed"}', '2019-06-26'),
  ('15e9e330-a1b8-5467-960f-e7d29e53e441', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-hb5-civic-education-curriculum-2021', 'Florida enacts HB 5, requiring an integrated K-12 civic education curriculum', '{"id":"FL-MANDATE-fl-hb5-civic-education-curriculum-2021","label":"Florida enacts HB 5, requiring an integrated K-12 civic education curriculum","sourceUrl":"https://flsenate.gov/Session/Bill/2021/5/Analyses/h0005z1.SEC.PDF","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://flsenate.gov/Session/Bill/2021/5/Analyses/h0005z1.SEC.PDF. Source is the Florida House final bill analysis, which states that it does not reflect the sponsor''s or House''s official position. The Florida Senate bill page also shows Chapter 2021-158 approved 6/22/2021. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida Legislature","mandateType":"statute","adoptionDate":"2021-06-22","dateGranularity":"day","effectiveFrom":"2021-07-01","statementText":"HB 5 has the Department of Education develop or approve an integrated K-12 civic education curriculum and the State Board set civic-minded expectations. It adds to U.S. Government a comparative discussion of ideologies that conflict with the founding principles of the United States, such as communism and totalitarianism, and creates the Portraits in Patriotism Act.","description":"HB 5 has the Department of Education develop or approve an integrated K-12 civic education curriculum and the State Board set civic-minded expectations. It adds to U.S. Government a comparative discussion of ideologies that conflict with the founding principles of the United States, such as communism and totalitarianism, and creates the Portraits in Patriotism Act.","verificationStatus":"primary-source-confirmed"}', '2021-06-22'),
  ('dc1c3f35-8fec-550f-9322-500c83a7b77a', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-sbe-civics-holocaust-standards-adopted-2021', 'Florida State Board of Education adopts revised civics and government standards and Holocaust education standards', '{"id":"FL-MANDATE-fl-sbe-civics-holocaust-standards-adopted-2021","label":"Florida State Board of Education adopts revised civics and government standards and Holocaust education standards","sourceUrl":"https://www.cbsnews.com/miami/news/florida-board-education-new-standards","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.cbsnews.com/miami/news/florida-board-education-new-standards. CBS Miami article dated July 14, 2021; WUSF and WUFT reports of the same Wednesday meeting agree on the content. The Department of Education site blocked fetching, so no official page was read. The 2021 House bill analysis expected adoption by summer 2021. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida State Board of Education","mandateType":"standards-revision","adoptionDate":"2021-07-14","dateGranularity":"day","statementText":"At its July 14, 2021 meeting the State Board adopted new civics, government and Holocaust education standards, along with changes to other subjects. News reports say the civics standards call for studying primary source documents about the American republic.","description":"At its July 14, 2021 meeting the State Board adopted new civics, government and Holocaust education standards, along with changes to other subjects. News reports say the civics standards call for studying primary source documents about the American republic.","verificationStatus":"secondary-source-only"}', '2021-07-14'),
  ('a09479b0-2750-5b9b-95d1-f1af9573f80b', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-sbe-rule-6a-1-09411-civic-education-curriculum-2021', 'Florida State Board of Education rule 6A-1.09411 sets requirements for K-12 civic education curriculum', '{"id":"FL-MANDATE-fl-sbe-rule-6a-1-09411-civic-education-curriculum-2021","label":"Florida State Board of Education rule 6A-1.09411 sets requirements for K-12 civic education curriculum","sourceUrl":"https://www.flrules.org/gateway/ruleNo.asp?id=6A-1.09411","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.flrules.org/gateway/ruleNo.asp?id=6A-1.09411. The flrules.org page shows only a summary and the history line; the list of required topics comes from law.cornell.edu/regulations/florida/Fla-Admin-Code-Ann-R-6A-1-09411. The State Board''s vote date was not confirmed. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida State Board of Education","mandateType":"other","adoptionDate":"2021-11-23","dateGranularity":"day","effectiveFrom":"2021-11-23","statementText":"Rule 6A-1.09411, effective November 23, 2021, sets requirements for the integrated civic education curriculum that districts and charter schools use in grades K-12. A copy of the rule on Cornell''s Legal Information Institute lists required content including the Declaration of Independence and the Constitution.","description":"Rule 6A-1.09411, effective November 23, 2021, sets requirements for the integrated civic education curriculum that districts and charter schools use in grades K-12. A copy of the rule on Cornell''s Legal Information Institute lists required content including the Declaration of Independence and the Constitution.","verificationStatus":"primary-source-confirmed"}', '2021-11-23'),
  ('512c04ed-7f47-5e6a-822f-e9357870b4af', 'florida-curriculum-repository', 'institutional-mandate-record', 'US-FL', 'openlpm-starter-draft', 'FL-MANDATE-fl-sbe-african-american-history-standards-adopted-2023', 'Florida State Board of Education approves stand-alone K-12 African American History standards', '{"id":"FL-MANDATE-fl-sbe-african-american-history-standards-adopted-2023","label":"Florida State Board of Education approves stand-alone K-12 African American History standards","sourceUrl":"https://www.wcjb.com/2023/07/19/florida-board-education-approves-african-american-history-standards/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.wcjb.com/2023/07/19/florida-board-education-approves-african-american-history-standards/. TV station report published July 19, 2023. The Florida Senate page for HB 7 (2022, Chapter 2022-72) directs the Department of Education to prepare African American history standards and curriculum. The standards drew public debate that this record does not summarize. Not reviewed by a person."},"jurisdiction":"US-FL","issuingBody":"Florida State Board of Education","mandateType":"standards-adoption","adoptionDate":"2023-07-19","dateGranularity":"day","statementText":"At its July 19, 2023 meeting in Orlando the State Board approved stand-alone African American History standards for kindergarten through grade 12.","description":"At its July 19, 2023 meeting in Orlando the State Board approved stand-alone African American History standards for kindergarten through grade 12.","verificationStatus":"secondary-source-only"}', '2023-07-19'),
  ('b369e569-48b5-5f55-a7bd-b849111f060d', 'pennsylvania-curriculum-repository', 'institutional-mandate-record', 'US-PA', 'openlpm-starter-draft', 'PA-MANDATE-pa-state-board-chapter-4-civics-economics-geography-history-standards-2003', 'Pennsylvania State Board of Education Chapter 4 regulation adding academic standards for civics and government, economics, geography and history takes effect', '{"id":"PA-MANDATE-pa-state-board-chapter-4-civics-economics-geography-history-standards-2003","label":"Pennsylvania State Board of Education Chapter 4 regulation adding academic standards for civics and government, economics, geography and history takes effect","sourceUrl":"https://www.pa.gov/agencies/stateboard/resources/regulations--policy/state-academic-standards","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.pa.gov/agencies/stateboard/resources/regulations--policy/state-academic-standards. Review dates come from the Independent Regulatory Review Commission page for Regulation 6-275 (irrc.state.pa.us/regulations/RegSrchRslts.cfm?ID=2238). The State Board''s own adoption vote date was not confirmed. Not reviewed by a person."},"jurisdiction":"US-PA","issuingBody":"Pennsylvania State Board of Education","mandateType":"standards-adoption","adoptionDate":"2003-01-11","dateGranularity":"day","effectiveFrom":"2003-01-11","statementText":"The State Board''s Chapter 4 regulation (No. 6-275) added statewide academic standards in civics and government, economics, geography and history. The review commission approved the final form on November 21, 2002, and the standards took effect on publication in the Pennsylvania Bulletin on January 11, 2003.","description":"The State Board''s Chapter 4 regulation (No. 6-275) added statewide academic standards in civics and government, economics, geography and history. The review commission approved the final form on November 21, 2002, and the standards took effect on publication in the Pennsylvania Bulletin on January 11, 2003.","verificationStatus":"primary-source-confirmed"}', '2003-01-11'),
  ('1bba11fe-1cb0-5267-b48d-8c7eb95a9c96', 'pennsylvania-curriculum-repository', 'institutional-mandate-record', 'US-PA', 'openlpm-starter-draft', 'PA-MANDATE-pa-act-35-civic-knowledge-assessment-2018', 'Pennsylvania enacts Act 35 of 2018 providing for an assessment of civic knowledge in schools', '{"id":"PA-MANDATE-pa-act-35-civic-knowledge-assessment-2018","label":"Pennsylvania enacts Act 35 of 2018 providing for an assessment of civic knowledge in schools","sourceUrl":"https://www.palegis.us/statutes/unconsolidated/law-information?sessYr=2018&sessInd=0&actNum=35","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.palegis.us/statutes/unconsolidated/law-information?sessYr=2018&sessInd=0&actNum=35. The legislature page gives the title, House Bill 564 and the June 19, 2018 enactment. The grade range and school year come from pasd.com/academics/assessment_information/act_35 and a Tyrone Eagle Eye News article. The act text does not state them. Not reviewed by a person."},"jurisdiction":"US-PA","issuingBody":"Pennsylvania General Assembly","mandateType":"statute","adoptionDate":"2018-06-19","dateGranularity":"day","statementText":"Act 35 of 2018 (House Bill 564) amends the Public School Code of 1949 to provide for an assessment of civic knowledge. School district and news pages describe a locally developed test of U.S. history, government and civics, given at least once in grades 7 to 12 beginning in 2020-21.","description":"Act 35 of 2018 (House Bill 564) amends the Public School Code of 1949 to provide for an assessment of civic knowledge. School district and news pages describe a locally developed test of U.S. history, government and civics, given at least once in grades 7 to 12 beginning in 2020-21.","verificationStatus":"primary-source-confirmed"}', '2018-06-19'),
  ('3120ac67-fe39-5ad2-840c-be2781a1303c', 'pennsylvania-curriculum-repository', 'institutional-mandate-record', 'US-PA', 'openlpm-starter-draft', 'PA-MANDATE-pa-irrc-approves-economics-personal-finance-standards-2024', 'Pennsylvania review commission approves the State Board''s updated Economics standards and new Personal Finance standards', '{"id":"PA-MANDATE-pa-irrc-approves-economics-personal-finance-standards-2024","label":"Pennsylvania review commission approves the State Board''s updated Economics standards and new Personal Finance standards","sourceUrl":"https://irrc.state.pa.us/regulations/RegSrchRslts.cfm?ID=3419","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://irrc.state.pa.us/regulations/RegSrchRslts.cfm?ID=3419. The effective date comes from the State Board standards page. That page says the standards were published in the Pennsylvania Bulletin on February 8, 2025, while the IRRC page lists publication as final on March 22, 2025, so the record uses the approval date. The State Board''s own vote date was not confirmed. Not reviewed by a person."},"jurisdiction":"US-PA","issuingBody":"Pennsylvania Independent Regulatory Review Commission","mandateType":"standards-revision","adoptionDate":"2024-12-05","dateGranularity":"day","effectiveFrom":"2026-07-01","statementText":"Regulation 6-354 updates Pennsylvania''s academic standards for Economics, together with Career Education and Work and Family and Consumer Sciences, and establishes new Personal Finance standards. The Independent Regulatory Review Commission approved it on December 5, 2024. The State Board lists July 1, 2026 as the effective date.","description":"Regulation 6-354 updates Pennsylvania''s academic standards for Economics, together with Career Education and Work and Family and Consumer Sciences, and establishes new Personal Finance standards. The Independent Regulatory Review Commission approved it on December 5, 2024. The State Board lists July 1, 2026 as the effective date.","verificationStatus":"primary-source-confirmed"}', '2024-12-05'),
  ('13a04c13-982f-5619-89d1-780c7cfde34c', 'tennessee-curriculum-repository', 'institutional-mandate-record', 'US-TN', 'openlpm-starter-draft', 'TN-MANDATE-tn-sbe-social-studies-standards-adopted-2017', 'Tennessee State Board of Education approves new Tennessee Academic Standards for Social Studies', '{"id":"TN-MANDATE-tn-sbe-social-studies-standards-adopted-2017","label":"Tennessee State Board of Education approves new Tennessee Academic Standards for Social Studies","sourceUrl":"http://www.csenewsnow.com/goodnews/2017/7/28/state-board-of-education-approves-new-tennessee-academic-standards-for-social-studies","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching http://www.csenewsnow.com/goodnews/2017/7/28/state-board-of-education-approves-new-tennessee-academic-standards-for-social-studies. Local news site reposting the State Board release, dated Jul 28 in the address and page. The State Board''s own site could not be fetched. A Chalkbeat article of April 21, 2017 reports the earlier first-reading vote. Not reviewed by a person."},"jurisdiction":"US-TN","issuingBody":"Tennessee State Board of Education","mandateType":"standards-adoption","adoptionDate":"2017-07-28","dateGranularity":"day","statementText":"The State Board voted unanimously on final reading to approve new Tennessee Academic Standards for Social Studies, to be used in classrooms from the 2019-20 school year. The release says changes made after first reading responded to public feedback and to a new state law on Tennessee history.","description":"The State Board voted unanimously on final reading to approve new Tennessee Academic Standards for Social Studies, to be used in classrooms from the 2019-20 school year. The release says changes made after first reading responded to public feedback and to a new state law on Tennessee history.","verificationStatus":"secondary-source-only"}', '2017-07-28'),
  ('c6e888b6-c7f9-542a-b7c2-f8a35da6772a', 'tennessee-curriculum-repository', 'institutional-mandate-record', 'US-TN', 'openlpm-starter-draft', 'TN-MANDATE-tn-general-assembly-tennessee-history-act-2017', 'Tennessee General Assembly passes the Senator Douglas Henry Tennessee History Act', '{"id":"TN-MANDATE-tn-general-assembly-tennessee-history-act-2017","label":"Tennessee General Assembly passes the Senator Douglas Henry Tennessee History Act","sourceUrl":"https://www.chalkbeat.org/tennessee/2017/5/12/21102781/at-11th-hour-lawmakers-mandate-a-whole-semester-of-tennessee-history-but-don-t-specify-where-it-will","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.chalkbeat.org/tennessee/2017/5/12/21102781/at-11th-hour-lawmakers-mandate-a-whole-semester-of-tennessee-history-but-don-t-specify-where-it-will. Public Chapter 482 and the Act''s name come from the State Board release reposted at csenewsnow.com; the fifth-grade placement comes from a Chalkbeat article of July 26, 2017. The exact signing date was not found, so the month of final passage is given. Not reviewed by a person."},"jurisdiction":"US-TN","issuingBody":"Tennessee General Assembly","mandateType":"statute","adoptionDate":"2017-05","dateGranularity":"month","statementText":"The legislature passed a law requiring a Tennessee history course, reported as a semester, without naming a grade. Chalkbeat reported it would take effect in the 2018-19 school year. The State Board later placed the content in fifth-grade standards starting in fall 2019.","description":"The legislature passed a law requiring a Tennessee history course, reported as a semester, without naming a grade. Chalkbeat reported it would take effect in the 2018-19 school year. The State Board later placed the content in fifth-grade standards starting in fall 2019.","verificationStatus":"secondary-source-only"}', ''),
  ('c0a08a4b-26c7-5f34-be5b-ae1b5af93963', 'tennessee-curriculum-repository', 'institutional-mandate-record', 'US-TN', 'openlpm-starter-draft', 'TN-MANDATE-tn-civics-test-graduation-requirement-tca-49-6-408', 'Tennessee law begins requiring high school students to take a U.S. civics test', '{"id":"TN-MANDATE-tn-civics-test-graduation-requirement-tca-49-6-408","label":"Tennessee law begins requiring high school students to take a U.S. civics test","sourceUrl":"https://codes.findlaw.com/tn/title-49-education/tn-code-sect-49-6-408/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://codes.findlaw.com/tn/title-49-education/tn-code-sect-49-6-408/. Date is the start date written in the statute; the enactment date was not found. FindLaw says its copy may not show the latest version of the law, and the state sites could not be fetched. Not reviewed by a person."},"jurisdiction":"US-TN","issuingBody":"Tennessee General Assembly","mandateType":"graduation-requirement","adoptionDate":"2017-01-01","dateGranularity":"day","effectiveFrom":"2017-01-01","statementText":"Under Tennessee Code 49-6-408, high school students were required from January 1, 2017 to take a civics test drawn from the 100 questions used for naturalization, with 70 percent as the passing score. Passing was optional at first. The current code makes a passing score a condition of the social studies credit for a full diploma.","description":"Under Tennessee Code 49-6-408, high school students were required from January 1, 2017 to take a civics test drawn from the 100 questions used for naturalization, with 70 percent as the passing score. Passing was optional at first. The current code makes a passing score a condition of the social studies credit for a full diploma.","verificationStatus":"secondary-source-only"}', '2017-01-01'),
  ('49ad4228-e09d-55aa-a875-cb2b0489d7d0', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-medienbildung-in-der-schule-2012', 'KMK adopts its declaration on media education in schools (Medienbildung in der Schule)', '{"id":"DE-MANDATE-kmk-medienbildung-in-der-schule-2012","label":"KMK adopts its declaration on media education in schools (Medienbildung in der Schule)","sourceUrl":"https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2012/2012_03_08_Medienbildung.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2012/2012_03_08_Medienbildung.pdf. The text refers to the earlier declaration ''Medienpädagogik in der Schule'' of 12.05.1995. The 2016 KMK strategy states that this 2012 text remains valid. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"recommendation","adoptionDate":"2012-03-08","dateGranularity":"day","statementText":"The KMK replaces its 1995 declaration on media pedagogy. It aims to make media education a compulsory task of schooling, covering learning with media and learning about media. It lists eight fields of action, from curricula and teacher education to copyright and data protection.","description":"The KMK replaces its 1995 declaration on media pedagogy. It aims to make media education a compulsory task of schooling, covering learning with media and learning about media. It lists eight fields of action, from curricula and teacher education to copyright and data protection.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die Erklärung „Medienbildung in der Schule“"}', '2012-03-08'),
  ('ec1628f9-997d-5a29-aaa4-cebee225d144', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-strategie-bildung-in-der-digitalen-welt-2016', 'KMK adopts the strategy ''Bildung in der digitalen Welt'' with a competence framework for all subjects', '{"id":"DE-MANDATE-kmk-strategie-bildung-in-der-digitalen-welt-2016","label":"KMK adopts the strategy ''Bildung in der digitalen Welt'' with a competence framework for all subjects","sourceUrl":"https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2016/2016_12_08-Bildung-in-der-digitalen-Welt.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2016/2016_12_08-Bildung-in-der-digitalen-Welt.pdf. Six areas: Suchen, Verarbeiten und Aufbewahren; Kommunizieren und Kooperieren; Produzieren und Präsentieren; Schützen und sicher Agieren; Problemlösen und Handeln; Analysieren und Reflektieren. The competences are integrated into the curricula of all subjects and no separate subject is created. The 2019 DigitalPakt agreement cites a version dated 7 December 2017; the PDF read here is the decision of 8 December 2016 in the version of 7 December 2017. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"strategy","adoptionDate":"2016-12-08","dateGranularity":"day","statementText":"The Länder agree to build digital competences into the curricula of all subjects from primary school on and to use digital learning environments systematically. The strategy sets a framework of six competence areas. Pupils entering Grundschule or Sekundarstufe I in 2018/19 should be able to acquire them by the end of compulsory schooling.","description":"The Länder agree to build digital competences into the curricula of all subjects from primary school on and to use digital learning environments systematically. The strategy sets a framework of six competence areas. Pupils entering Grundschule or Sekundarstufe I in 2018/19 should be able to acquire them by the end of compulsory schooling.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die Strategie „Bildung in der digitalen Welt“ mit einem Kompetenzrahmen für alle Fächer"}', '2016-12-08'),
  ('73bcf049-9f1e-5b46-9084-5af507b56dd8', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-demokratiebildung-empfehlung-2018', 'KMK adopts its revised recommendation on democracy education in schools', '{"id":"DE-MANDATE-kmk-demokratiebildung-empfehlung-2018","label":"KMK adopts its revised recommendation on democracy education in schools","sourceUrl":"https://www.kmk.org/bildungsministerkonferenz/bildungsthemen/demokratiebildung.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/bildungsministerkonferenz/bildungsthemen/demokratiebildung.html. The original was adopted on 06.03.2009; this record covers the version dated 11.10.2018. The document text was read from the copy hosted by the Federal Agency for Civic Education (https://www.bpb.de/medien/278816/Beschluss_Demokratieerziehung.pdf), whose title line reads ''Beschluss der Kultusministerkonferenz vom 06.03.2009 i. d. F. vom 11.10.2018''. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"recommendation","adoptionDate":"2018-10-11","dateGranularity":"day","statementText":"The KMK updates its 2009 recommendation. It describes the school as a place where democracy is taught and practised, bases teaching on fundamental rights and human dignity, and names the Beutelsbach Consensus with its controversy principle as a basis of democratic learning. A passage on digitalisation calls for critical media competence.","description":"The KMK updates its 2009 recommendation. It describes the school as a place where democracy is taught and practised, bases teaching on fundamental rights and human dignity, and names the Beutelsbach Consensus with its controversy principle as a basis of democratic learning. A passage on digitalisation calls for critical media competence.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die neu gefasste Empfehlung „Demokratie als Ziel, Gegenstand und Praxis historisch-politischer Bildung und Erziehung in der Schule“"}', '2018-10-11'),
  ('ee2a521e-235a-5273-85af-05f174dc63c6', 'germany-curriculum-repository', 'policy-timeline-event', 'DE', 'openlpm-starter-draft', 'DE-EVENT-federal-digitalpakt-schule-agreement-2019', 'Federal government and the Länder sign the DigitalPakt Schule agreement worth 5 billion euros', '{"id":"DE-EVENT-federal-digitalpakt-schule-agreement-2019","slug":"federal-digitalpakt-schule-agreement-2019","label":"Federal government and the Länder sign the DigitalPakt Schule agreement worth 5 billion euros","sourceUrl":"https://digitalpakt.rlp.de/fileadmin/digitalpakt/Bund_Digitalpakt_VV_2019-2024.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://digitalpakt.rlp.de/fileadmin/digitalpakt/Bund_Digitalpakt_VV_2019-2024.pdf. The PDF is the Bundesanzeiger notice BAnz AT 14.06.2019 B2, hosted by Rhineland-Palatinate. The signature block shows the federal minister signing in Berlin on 16 May 2019 and the Länder signing between 2 and 10 May 2019. The effective date of 17 May 2019 follows from section 20(2), which makes the agreement effective the day after the last signature. Not reviewed by a person."},"jurisdiction":"DE","dateStart":"2019-05-16","dateGranularity":"day","eventType":"funding-launched","temporalStatus":"past-completed","description":"Under Article 104c of the Basic Law, the federal government provides 5 billion euros over five years for digital infrastructure in schools. The Länder add at least 10 percent of the funded investments and pledge their own measures. The agreement takes effect the day after the last signature.","verificationStatus":"primary-source-confirmed","labelDe":"Bund und Länder unterzeichnen die Verwaltungsvereinbarung DigitalPakt Schule über 5 Milliarden Euro"}', '2019-05-16'),
  ('3da6023d-7021-539a-b0fd-ff9165d09f2b', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-ergaenzung-lehren-und-lernen-digitale-welt-2021', 'KMK adopts ''Lehren und Lernen in der digitalen Welt'', a supplement to its digital education strategy', '{"id":"DE-MANDATE-kmk-ergaenzung-lehren-und-lernen-digitale-welt-2021","label":"KMK adopts ''Lehren und Lernen in der digitalen Welt'', a supplement to its digital education strategy","sourceUrl":"https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2021/2021_12_09-Lehren-und-Lernen-Digi.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/veroeffentlichungen_beschluesse/2021/2021_12_09-Lehren-und-Lernen-Digi.pdf. The KMK topic page for education in the digital world lists this text as a 2021 supplement to the 2016 strategy. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"strategy","adoptionDate":"2021-12-09","dateGranularity":"day","statementText":"The supplement deepens the 2016 strategy with a focus on teaching and learning. It covers pupils'' competences, the potential of digital learning, examination culture, school development, digitally supported lesson design, teacher competences and teacher education. It takes in comments from an April 2021 hearing and recommendations of the SWK.","description":"The supplement deepens the 2016 strategy with a focus on teaching and learning. It covers pupils'' competences, the potential of digital learning, examination culture, school development, digitally supported lesson design, teacher competences and teacher education. It takes in comments from an April 2021 hearing and recommendations of the SWK.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die Ergänzung „Lehren und Lernen in der digitalen Welt“ zur Strategie „Bildung in der digitalen Welt“"}', '2021-12-09'),
  ('71f80513-933d-56c4-bd4e-d6e713318b35', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-epa-informatik-abitur-2004', 'KMK adopts revised unified Abitur examination requirements (EPA) for Informatik', '{"id":"DE-MANDATE-kmk-epa-informatik-abitur-2004","label":"KMK adopts revised unified Abitur examination requirements (EPA) for Informatik","sourceUrl":"https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/1989/1989_12_01-EPA-Informatik.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/1989/1989_12_01-EPA-Informatik.pdf. The original was adopted on 01.12.1989. The KMK decisions list for general education still shows this text as its Informatik document for the Abitur, while the Biologie, Chemie and Physik EPA are marked as replaced by Bildungsstandards from the 2025 Abitur. The Informatik section of the KMK MINT page lists only EPA texts (EPA Informatik and EPA berufliche Informatik) and no Bildungsstandards. A later check could not reopen the KMK page, so the statement that Informatik has no Bildungsstandards is unconfirmed. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"standards-adoption","adoptionDate":"2004-02-05","dateGranularity":"day","statementText":"The EPA Informatik describe the competences and content that Abitur tasks in Informatik must cover, the three levels of task demand, and sample tasks for written and oral exams. On 12 March 2004 the KMK asked the Länder to apply the revised text by the 2007 Abitur at the latest.","description":"The EPA Informatik describe the competences and content that Abitur tasks in Informatik must cover, the three levels of task demand, and sample tasks for written and oral exams. On 12 March 2004 the KMK asked the Länder to apply the revised text by the 2007 Abitur at the latest.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die neu gefassten Einheitlichen Prüfungsanforderungen in der Abiturprüfung Informatik"}', '2004-02-05'),
  ('6f8bbf6d-b8f7-5920-887b-0910e17f4659', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-epa-sozialkunde-politik-abitur-2005', 'KMK adopts revised unified Abitur examination requirements (EPA) for Sozialkunde/Politik', '{"id":"DE-MANDATE-kmk-epa-sozialkunde-politik-abitur-2005","label":"KMK adopts revised unified Abitur examination requirements (EPA) for Sozialkunde/Politik","sourceUrl":"https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/1989/1989_12_01-EPA-Sozialkunde-Politik.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/1989/1989_12_01-EPA-Sozialkunde-Politik.pdf. The original was adopted on 01.12.1989. The three principles are Überwältigungsverbot, Kontroversitätsgebot and Berücksichtigung der Interessenlagen der Schülerinnen und Schüler; the four competences are Sach- und Analysekompetenz, Urteilskompetenz, Methodenkompetenz and Handlungskompetenz. A separate KMK text sets EPA for Wirtschaft (version of 16.11.2006). Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"standards-adoption","adoptionDate":"2005-11-17","dateGranularity":"day","statementText":"The preamble names political maturity and the capacity for democracy as guiding aims. It builds the subject on three principles (no overwhelming of pupils, controversy, pupils'' interests) and on four competences: analysis, judgement, methods and action. The Länder were asked to apply the text by the 2009 Abitur at the latest.","description":"The preamble names political maturity and the capacity for democracy as guiding aims. It builds the subject on three principles (no overwhelming of pupils, controversy, pupils'' interests) and on four competences: analysis, judgement, methods and action. The Länder were asked to apply the text by the 2009 Abitur at the latest.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt die neu gefassten Einheitlichen Prüfungsanforderungen in der Abiturprüfung Sozialkunde/Politik"}', '2005-11-17'),
  ('b181440e-9b2f-5bd1-a35f-970f6cbf9fdb', 'germany-curriculum-repository', 'policy-timeline-event', 'DE', 'openlpm-starter-draft', 'DE-EVENT-swk-stellungnahme-demokratiebildung-2024', 'KMK''s scientific commission (SWK) publishes its statement on democracy education in schools', '{"id":"DE-EVENT-swk-stellungnahme-demokratiebildung-2024","slug":"swk-stellungnahme-demokratiebildung-2024","label":"KMK''s scientific commission (SWK) publishes its statement on democracy education in schools","sourceUrl":"https://swk-bildung.org/pressemitteilungen/stellungnahme-zur-demokratiebildung-swk-empfiehlt-staerkung-der-faecher-politik-und-geschichte/","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://swk-bildung.org/pressemitteilungen/stellungnahme-zur-demokratiebildung-swk-empfiehlt-staerkung-der-faecher-politik-und-geschichte/. This is advice to the Länder. The KMK president said in the same press release that the KMK would examine the recommendations. The full statement PDF (https://www.swk-bildung.org/content/uploads/2024/06/SWK-2024-Stellungnahme_Demokratiebildung.pdf) was also read and says it was adopted by the commission members in July 2024. Not reviewed by a person."},"jurisdiction":"DE","dateStart":"2024-07-11","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","description":"The SWK, an independent scientific advisory body of the KMK, makes seven recommendations. They call for shared competence goals and continuous teaching in Politik and Geschichte from primary school to the end of Sekundarstufe I, and for democracy education as a principle in all subjects.","verificationStatus":"primary-source-confirmed","labelDe":"Die Ständige Wissenschaftliche Kommission der KMK veröffentlicht die Stellungnahme „Demokratiebildung als Auftrag der Schule“"}', '2024-07-11'),
  ('fbb0bcd2-b850-5cd2-acd9-17236396e892', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-kmk-eckpunkte-medien-informatische-bildung-grundschule-2024', 'KMK adopts key points for anchoring media education and informatics education in primary school', '{"id":"DE-MANDATE-kmk-eckpunkte-medien-informatische-bildung-grundschule-2024","label":"KMK adopts key points for anchoring media education and informatics education in primary school","sourceUrl":"https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2024/2024_11_28-Medien-inform-Bildung-Grundschule.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2024/2024_11_28-Medien-inform-Bildung-Grundschule.pdf. The paper builds on the ''Vereinbarung zur Arbeit in der Grundschule'' of 15.03.2024 and also covers teacher education. It states: ''Ein Unterrichtsfach Informatik in der Grundschule ist derzeit nicht vorgesehen.'' Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Standing Conference of the Ministers of Education (KMK)","mandateType":"recommendation","adoptionDate":"2024-11-28","dateGranularity":"day","statementText":"The key points treat digital media education and informatics education as cross-subject areas of Grundschule, based on the KMK competence framework. A separate Informatik subject in primary school is currently not planned. Bildungsstandards, including possible first standards for Sachunterricht, should take both areas into account.","description":"The key points treat digital media education and informatics education as cross-subject areas of Grundschule, based on the KMK competence framework. A separate Informatik subject in primary school is currently not planned. Bildungsstandards, including possible first standards for Sachunterricht, should take both areas into account.","verificationStatus":"primary-source-confirmed","labelDe":"Die KMK beschließt das Eckpunktepapier zur Verankerung von Medienbildung und informatischer Bildung in der Grundschule"}', '2024-11-28'),
  ('ca78339a-217a-5311-9d94-ff84430cfbbd', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-bmk-social-media-erklaerung-schule-2026', 'Bildungsministerkonferenz adopts a declaration on handling social media in schools', '{"id":"DE-MANDATE-bmk-social-media-erklaerung-schule-2026","label":"Bildungsministerkonferenz adopts a declaration on handling social media in schools","sourceUrl":"https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2026/2026_06_12-Social-Media-Erklaerung.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2026/2026_06_12-Social-Media-Erklaerung.pdf. The text builds on the 2016 strategy and its 2021 supplement and welcomes a federal expert commission on child and youth protection in the digital world. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Bildungsministerkonferenz (BMK), acting for the KMK","mandateType":"other","adoptionDate":"2026-06-12","dateGranularity":"day","statementText":"The Länder set three aims: raise awareness, build competence and protect pupils. Measures include covering social media in curricula across subjects, supporting parents, school rules on device use that protect the concentration and wellbeing of younger pupils, and teacher training on hate speech.","description":"The Länder set three aims: raise awareness, build competence and protect pupils. Measures include covering social media in curricula across subjects, supporting parents, school rules on device use that protect the concentration and wellbeing of younger pupils, and teacher training on hate speech.","verificationStatus":"primary-source-confirmed","labelDe":"Die Bildungsministerkonferenz beschließt eine Erklärung zum Umgang mit Social Media im schulischen Bereich"}', '2026-06-12'),
  ('193a33e0-c9cc-5ec9-bf7b-0ce1c1b63277', 'germany-curriculum-repository', 'policy-timeline-event', 'DE', 'openlpm-starter-draft', 'DE-EVENT-federal-digitalpakt-2-0-start-2026', 'Digitalpakt 2.0 starts: federal government and Länder release 5 billion euros for digital education', '{"id":"DE-EVENT-federal-digitalpakt-2-0-start-2026","slug":"federal-digitalpakt-2-0-start-2026","label":"Digitalpakt 2.0 starts: federal government and Länder release 5 billion euros for digital education","sourceUrl":"https://www.kmk.org/aktuelles/pressearchiv/mitteilung/digitalpakt-20-startet-am-1-september-bund-und-laender-bringen-milliardeninvestitionen-fuer-die-digitale-bildung-auf-den-weg.html","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/aktuelles/pressearchiv/mitteilung/digitalpakt-20-startet-am-1-september-bund-und-laender-bringen-milliardeninvestitionen-fuer-die-digitale-bildung-auf-den-weg.html. The KMK press release is dated 01.09.2026. A BMBFSFJ press release of 19.08.2026 (https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/pressemitteilungen/digitalpakt-2-0-startet-am-1-september-293650) was also read and confirms the signatures. A joint declaration of 13.12.2024, adopted at the 2nd Bildungsministerkonferenz, named a total term of six years; the 2026 release gives five years. Not reviewed by a person."},"jurisdiction":"DE","dateStart":"2026-09-01","dateGranularity":"day","eventType":"funding-launched","temporalStatus":"past-completed","description":"After all Länder signed the administrative agreement, the federal education minister signed it too, which clears federal payments. It applies from 1 January 2026 for five years, with 5 billion euros split equally between the Bund and the Länder. Strand I funds school digital infrastructure; strand III adds 250 million euros of federal money for research.","verificationStatus":"primary-source-confirmed","labelDe":"Der Digitalpakt 2.0 startet: Bund und Länder stellen 5 Milliarden Euro für digitale Bildung bereit"}', '2026-09-01'),
  ('59b72de3-e2c2-50f5-a743-55819edccb83', 'germany-curriculum-repository', 'institutional-mandate-record', 'DE', 'openlpm-starter-draft', 'DE-MANDATE-bmk-kompetenzrahmen-digitale-welt-ki-aktualisierung-2026', 'Bildungsministerkonferenz updates the KMK digital competence framework for artificial intelligence', '{"id":"DE-MANDATE-bmk-kompetenzrahmen-digitale-welt-ki-aktualisierung-2026","label":"Bildungsministerkonferenz updates the KMK digital competence framework for artificial intelligence","sourceUrl":"https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2026/2026_10_16-KI-Kompetenzrahmen.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Researched by fetching https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2026/2026_10_16-KI-Kompetenzrahmen.pdf. The four orientation terms are ''Mit KI bewusst umgehen'', ''KI kreativ anwenden'', ''KI gezielt einsetzen'' and ''KI aktiv mitgestalten''. This decision is twelve days old at the time of research, so later corrections on the KMK site are possible. Not reviewed by a person."},"jurisdiction":"DE","issuingBody":"Bildungsministerkonferenz (BMK), acting for the KMK","mandateType":"other","adoptionDate":"2026-10-16","dateGranularity":"day","statementText":"The update adds AI-related content to the six competence areas of the KMK framework, whose structure stays unchanged. It draws on the OECD and European Commission AI Literacy Framework, whose final version appeared in 2026, and uses four orientation terms for AI competence.","description":"The update adds AI-related content to the six competence areas of the KMK framework, whose structure stays unchanged. It draws on the OECD and European Commission AI Literacy Framework, whose final version appeared in 2026, and uses four orientation terms for AI competence.","verificationStatus":"primary-source-confirmed","labelDe":"Die Bildungsministerkonferenz beschließt die Aktualisierung des KMK-Kompetenzrahmens „Bildung in der digitalen Welt“ im Kontext Künstlicher Intelligenz"}', '2026-10-16')
) AS v(id, repo_slug, record_type, jurisdiction, source_repo, source_record_id, title, content, event_date)
JOIN projects p ON p.slug = v.repo_slug
ON CONFLICT (source_repo, source_record_id) DO NOTHING;

