-- ============================================================================
-- 3. Further proposed links
-- ============================================================================
-- Rows are skipped when the part or the record is missing, or when the pair is already linked in any way.

-- bio: 24 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', 'd17a7dc1-5804-4cd0-81e9-a6be371db346', 'proposed_relates_to', 'In 2005 Judge Jones ruled the Dover intelligent-design policy unconstitutional and found intelligent design to be a relabeled form of creationism. The ruling shows how evolution teaching is protected in US classrooms, the setting for this strand''s content.'),
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', '70566c19-3c0b-455e-92d9-0e8428eb702b', 'proposed_relates_to', 'In 1989 California''s Curriculum Commission endorsed a Science Framework that made evolution one of four central organizing themes. A state treating evolution as a unifying idea for science teaching parallels the role this strand has in Bio-Core.'),
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', '8ebc5075-1950-4b7f-b043-08037f75ad1d', 'proposed_relates_to', 'This Florida record names the 2008 standard SC.912.L.15 (Diversity and Evolution of Living Organisms, grades 9-12) as an informal crosswalk target for this strand''s natural selection and adaptation content. The record itself calls the mapping informal.'),
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', '841f3a3e-7d04-4458-b301-7220522ac27e', 'proposed_contrasts_with', 'Tennessee''s 2012 law shields teachers who critique the ''scientific weaknesses'' of theories that cause debate, and it names biological evolution among them. It contrasts with a strand that teaches natural selection as a full explanatory model.'),
  ('d1b088f7-a940-5d5e-a5bc-45c0a049d351', '755e430b-2419-41ee-9c6b-ca0f877c1df9', 'proposed_contrasts_with', 'In late 2007 at least 12 Florida county school boards passed resolutions urging the State Board to revise draft standards over how evolution is presented as fact. This is local pushback against the kind of content this strand teaches.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', '5331a5c2-be7d-4d3f-80bb-edef7d83689b', 'proposed_relates_to', 'The US Supreme Court held in 1968 that a state cannot ban the teaching of evolution, because the ban rested on one religious doctrine. It is the federal baseline for teaching the evolution content this strand covers.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', '94a107a0-8c89-46a6-9e22-4141359f62dd', 'proposed_relates_to', 'In 1970 the Mississippi Supreme Court struck down its state''s anti-evolution law, reasoning that Epperson had already settled the question. Mississippi and Arkansas were the only two states with such teaching bans left in 1968.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', 'b570a7a8-dd9b-48d2-bf5d-905d3381d993', 'proposed_relates_to', 'In 1987 the Supreme Court struck down a Louisiana law requiring ''creation science'' alongside evolution, finding its purpose was to advance a religious view about the creation of humankind. It sets a limit on competing origin accounts in science class.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', 'da048bef-e97e-4f37-b313-831f8ebb72d9', 'proposed_contrasts_with', 'Tennessee''s 1973 law required biology textbooks to give equal emphasis to the Genesis account and to carry a disclaimer about evolution''s status as scientific fact. Courts struck it down in 1975. It contrasts with this strand''s science-based account of diversity.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', '7a22e490-3ac3-4348-96c4-f7087de65719', 'proposed_contrasts_with', 'Dover''s 2004 policy told students about ''gaps/problems in Darwin''s theory'' and offered intelligent design as an alternative explanation of the origin of life. It contrasts with this strand''s evolutionary account of species and diversity.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', 'f6c75e6e-d735-4a66-9cb1-a4e5dd49111a', 'proposed_relates_to', 'This record traces the US evolution-education conflict from Tennessee''s 1925 Butler Act through later ''academic freedom'' laws, across several states and legal mechanisms. It gives the policy background for teaching this strand''s content.'),
  ('d8df353a-aa76-5d37-b5b4-a0cd3f1d4860', 'e562d004-1560-493f-857a-1200aa3c43ba', 'proposed_contrasts_with', 'Bayern publishes a separate Fachlehrplan for each Jahrgangsstufe (for example Biologie 8 and Biologie 9), with no combined grade band. Bio-Core groups content into four bands (K-2, 3-5, 6-8, 9-12), so the grain of the two plans differs.'),
  ('d8df353a-aa76-5d37-b5b4-a0cd3f1d4860', '89b79579-b337-48c2-adc4-5541659af832', 'proposed_relates_to', 'Tennessee''s 2022 science standards include a dedicated strand on Heredity, Inheritance and Variation of Traits (LS3) beside Biological Change (LS4). That heredity strand covers the same ground as this strand.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'cb0f970e-1a51-4e98-87a4-b8286eb4a195', 'proposed_contrasts_with', 'Per reviewers at public-comment sessions, Florida''s 2026 draft high-school life-science standards lack gene flow and genetic drift. This substrand teaches allele-frequency change and the role of drift at the same level, so the draft stands in contrast.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '351480ce-0c91-4a88-a16c-c81ac8bd076f', 'proposed_relates_to', 'Florida''s 2008 benchmark SC.912.L.15.1 asks students to explain how evolution is supported by the fossil record and molecular biology, among other lines. It matches this substrand''s indicator on judging common ancestry against several independent lines of evidence.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '9f927475-8340-423a-b56a-cf3563a05cb0', 'proposed_relates_to', 'Tennessee benchmark BIO1.LS4.1 has students analyze data showing that common ancestry and evolution are supported by multiple lines of evidence, such as DNA sequences and the fossil record. It is close to this substrand''s indicator on evaluating a common-ancestry claim.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'eb76b968-2d81-43e4-9e73-3c37ece37078', 'proposed_relates_to', 'Pennsylvania''s 2022 standards include benchmark 3.1.9-12.S, in the strand Evidence of Common Ancestry and Diversity, on communicating that common ancestry and evolution rest on multiple lines of empirical evidence. It targets the same high-school skill as this substrand.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '865165e5-eebf-4530-9f9c-ea313a8f1147', 'proposed_relates_to', 'Sachsen-Anhalt''s Sekundarschule Biologie plan for grades 9/10 asks students to show shared structures of organisms as a result of phylogenetic development, with the descent of humans as the example. The record compares this with the Gymnasium''s grades 11/12.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '39ba2fd3-3a0d-4c90-92e8-58d2332095f6', 'proposed_relates_to', 'This cross-state comparison puts human-evolution content in Thüringen at Klasse 10 and in Sachsen and Sachsen-Anhalt at the upper grades 11/12. It shows where three states place the phylogeny and evidence topics this substrand covers.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '55495405-b0c8-4470-b1e7-ef4dbbd7c92a', 'proposed_relates_to', 'Thüringen''s Regelschule plan for grades 9/10 has students explain the descent of modern humans with a simplified hominid cladogram and the evidence for reconstructing it. The record notes this content is guaranteed only on the Realschulabschluss track.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'cb0f970e-1a51-4e98-87a4-b8286eb4a195', 'proposed_relates_to', 'Per reviewers, Florida''s 2026 draft middle-school standards mention natural selection without an explicit evolution framing. The record bears on how a grades 6-8 treatment of natural selection is named, which is the focus of this substrand.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'f2397dfb-0ab1-495a-96a0-995b5c50092e', 'proposed_relates_to', 'This informal crosswalk maps Tennessee''s Biological Change strands in grade 8 (8.LS4) and Biology I (BIO1.LS4) to Bio-Core''s natural selection content. The grade 8 part falls inside this substrand''s band.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'eb76b968-2d81-43e4-9e73-3c37ece37078', 'proposed_relates_to', 'Pennsylvania benchmark 3.1.9-12.T asks students to explain evolution through four factors, including heritable variation and the proliferation of better-surviving organisms. Bio-Core teaches this four-part model at grades 6-8, earlier than the standard does.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', '9f927475-8340-423a-b56a-cf3563a05cb0', 'proposed_relates_to', 'Tennessee benchmark BIO1.LS4.3 asks students to analyze how natural selection depends on heritable genetic variation and differential survival. These match the components of this substrand''s four-part mechanism.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- social: 9 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('067d4563-07b7-5c5c-8e9c-1dba9b610402', 'a3d02265-8673-500a-b86e-25c12aa505e1', 'proposed_relates_to', 'The C3 Framework guides states revising their social studies standards, with civics and history among its fields and an inquiry approach to teaching. As a K-12 civics reference it is a candidate comparison for this strand.'),
  ('067d4563-07b7-5c5c-8e9c-1dba9b610402', '7e2d942a-f8d4-5b63-a912-ac00aba48b99', 'proposed_relates_to', 'The Roadmap is a K-12 framework for history and civic education built around seven themes, offered as a starting point for standards and lessons. Its civic side can be compared with how this strand builds from groups to institutions.'),
  ('067d4563-07b7-5c5c-8e9c-1dba9b610402', '73bcf049-9f1e-5b46-9084-5af507b56dd8', 'proposed_relates_to', 'The 2018 KMK recommendation treats the school as a place where democracy is taught and practised and names the Beutelsbach Consensus and its controversy principle. It gives a national German statement of civic aims to compare with this strand.'),
  ('067d4563-07b7-5c5c-8e9c-1dba9b610402', 'b181440e-9b2f-5bd1-a35f-970f6cbf9fdb', 'proposed_relates_to', 'The SWK statement calls for shared competence goals and continuous Politik and Geschichte teaching from primary school to the end of Sekundarstufe I, with democracy education in all subjects. That span overlaps most of this strand''s grade range.'),
  ('925d0b84-162d-5a26-a26c-c15db8863af1', 'a3d02265-8673-500a-b86e-25c12aa505e1', 'proposed_relates_to', 'The C3 Framework covers geography and history alongside civics and economics and organizes teaching around inquiry. Its history and geography parts can be compared with this strand''s work on why societies differ and change.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', '218f2a76-bbbe-573c-bae4-1d4aada4d412', 'proposed_relates_to', 'The revised Grades 9-12 framework places Participation in Government and Civics and Economics in grade 12. This final-year course is a candidate counterpart for this substrand''s work on formal institutions and incentives.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', '6f8bbf6d-b8f7-5920-887b-0910e17f4659', 'proposed_relates_to', 'The Abitur requirements for Sozialkunde/Politik name political maturity and the capacity for democracy as aims and build on four competences, among them analysis and judgement. They give a German upper-secondary endpoint to compare with this substrand.'),
  ('504c7645-bc71-5a81-a114-cd2d598d1621', '218f2a76-bbbe-573c-bae4-1d4aada4d412', 'proposed_relates_to', 'The revised Grades 9-12 framework sets Global History and Geography for grades 9 and 10 and United States History and Government for grade 11. These history courses are candidate places to compare with this substrand''s work on explaining large-scale change.'),
  ('504c7645-bc71-5a81-a114-cd2d598d1621', 'b66214f4-769b-48a1-bdf9-b1c46194de68', 'proposed_relates_to', 'Sachsen''s grade-11 Gemeinschaftskunde unit on social structure and social change cross-references geography topics on population development and demographic change. It is a German upper-secondary case of teaching social change.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- computational: 12 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'be82d592-a481-5648-8575-30b832c7951f', 'proposed_relates_to', 'Five organizations released a K-12 framework of core computer science concepts and practices that describes how understanding grows over time. That growth-over-time design parallels this strand''s K-2 to 9-12 progression.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', '22d43498-6714-5f7c-a9c8-d3df3c69d903', 'proposed_relates_to', 'CSTA published revised K-12 computer science standards aligned to the 2016 framework, updating its first comprehensive set from 2011. As a full K-12 standards set it is a direct comparison point for this strand''s grade bands.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'b001256a-0c62-5cc1-a983-843490197ffc', 'proposed_relates_to', 'CSTA''s 2026 PK-12 standards were finalized by 25 writers from 18 states and start at pre-kindergarten. This strand starts at K-2, so the pre-K years have no counterpart in it, while the K-12 span lets the two sets be compared band by band.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', '7fcff5d2-e1c1-5b3b-aab4-a742465c5a13', 'proposed_relates_to', 'California''s first K-12 computer science standards cover core concepts such as algorithms and programming and practices such as creating computational artifacts. These are the central topics of this strand across its bands.'),
  ('a652b045-d46e-5ad9-acfe-052eea355407', '34658a80-bb0f-46a2-bbfc-7750a2d17deb', 'proposed_relates_to', 'Informatik in three states centers on a Modellieren competency. In Sachsen (Klassenstufen 7-10) pupils build models, then implement and test them. That matches this strand''s focus on building and testing models and simulations.'),
  ('a652b045-d46e-5ad9-acfe-052eea355407', 'e86b117f-3ddd-4a69-9b9e-3ea41c14a95b', 'proposed_relates_to', 'The Modellieren und Implementieren competency also appears in Sachsen''s Oberschule Informatik (7-10) and Sachsen-Anhalt''s new Sekundarschule Informatik (5-8). It shows modelling as a core aim of lower secondary computing, as in this strand.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', '34658a80-bb0f-46a2-bbfc-7750a2d17deb', 'proposed_relates_to', 'Sachsen''s compulsory Gymnasium Informatik (Klassenstufen 7-10) has pupils implement, test, evaluate and revise their own solutions. The testing and revising step is close to the testing work in this 6-8 part.'),
  ('a652b045-d46e-5ad9-acfe-052eea355407', '39370f72-261d-5cef-9b7a-081a773bc083', 'proposed_relates_to', 'Executive Order 14277 calls for online K-12 AI literacy resources and a White House task force on AI education. This strand''s grade 9-12 part compares machine learning with other systems, so the AI literacy goal overlaps with it.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', '39370f72-261d-5cef-9b7a-081a773bc083', 'proposed_relates_to', 'The order gives priority to high school AI courses. This 9-12 part compares machine learning, search and distributed systems, so it covers the same school stage and the same subject area.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', '59b72de3-e2c2-50f5-a743-55819edccb83', 'proposed_relates_to', 'The Bildungsministerkonferenz update adds AI content to the six KMK competence areas and draws on the OECD and European Commission AI literacy framework. This 9-12 part on machine learning is the closest part of the Core for AI content.'),
  ('bd2869a3-e2d1-58c1-9878-0c17f2a21c68', 'fbb0bcd2-b850-5cd2-acd9-17236396e892', 'proposed_relates_to', 'The KMK key points treat informatics education as a cross-subject area of Grundschule and currently plan no separate Informatik subject there. This frames how step-by-step work for the youngest pupils could be offered in German primary schools.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'fbb0bcd2-b850-5cd2-acd9-17236396e892', 'proposed_relates_to', 'The KMK key points place informatics education in primary school as a cross-subject area, with no separate subject planned, and ask that Bildungsstandards take it into account. This frames where this grades 3-5 part could sit in Germany.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- interdisciplinary: 9 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('e820dc2d-9317-57d1-8475-22a701fc486a', 'ca78339a-217a-5311-9d94-ff84430cfbbd', 'proposed_relates_to', 'The Länder''s 2026 declaration on social media aims to build pupils'' competence and protect them, and calls for covering social media in curricula across subjects. This part uses a social media platform as its example of a shaped information environment.'),
  ('e820dc2d-9317-57d1-8475-22a701fc486a', '508ad428-596b-45af-9986-d4e1527f2f19', 'proposed_relates_to', 'Thüringen''s Regelschule Informatik elective for grades 9 and 9/10 has students describe the history of information and communication technology and take a position on the chances and risks of informatics systems. It fits this part''s technology and information-environment focus.'),
  ('06af1b7b-19bb-5d77-87ac-52f34650f556', 'fcbccc61-96a5-465c-a541-d50b8f544ed3', 'proposed_relates_to', 'California''s Board of Education adopted a 1989 policy limiting the science curriculum to ''observable facts and testable hypotheses''. It states the testability standard that this strand teaches students to apply to their own guesses and to scientific ideas.'),
  ('9d59fa89-cdc8-5147-a71e-95175b25fcee', '26cb8c93-b07b-4ee2-b461-dfbbb4915f77', 'proposed_relates_to', 'This draft German principle proposes organizing interdisciplinary teaching around one integrating question, what it means to be human, so that linking subjects has a shared object of inquiry. This strand pulls evolutionary and cultural concepts into one shared vocabulary.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', 'eb76b968-2d81-43e4-9e73-3c37ece37078', 'proposed_relates_to', 'Pennsylvania''s 2022 high school life science standards ask students to construct an evidence-based explanation that evolution results from four factors, including heritable variation. They give the biology reference point for this part''s comparison of selection across domains.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', '9f927475-8340-423a-b56a-cf3563a05cb0', 'proposed_relates_to', 'Tennessee''s 2022 Biology I benchmarks ask students to analyze data showing that natural selection is influenced by population growth potential and heritable genetic variation. This is the state''s biological definition of selection, which this part sets beside the other three.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', '661e3269-c5e4-4419-87a0-a4519bce60f0', 'proposed_relates_to', 'Sachsen''s Oberschule Biologie plan for grade 10 lists the stages of human evolution and, in the same learning area, cultural evolution with language and cultures. It shows a state biology course naming cultural evolution next to the biological case.'),
  ('d2dc3119-7af8-55d8-8bfe-b63a4ec56acb', '34658a80-bb0f-46a2-bbfc-7750a2d17deb', 'proposed_relates_to', 'Three German states center Informatik on modeling. The Sachsen text for grades 7 to 10 has students develop models, then test and revise their solution, a cycle that fits this part''s focus on improving an idea through small changes.'),
  ('5e4cdc6e-5c25-5f21-a833-4c0859a609da', '70566c19-3c0b-455e-92d9-0e8428eb702b', 'proposed_relates_to', 'California''s Curriculum Commission endorsed a 1989 Science Framework making evolution one of four central organizing themes. This strand organizes content across domains around one shared pattern of variation and selection.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);
